package orchestrator

import (
	"encoding/hex"
	"testing"
)

func mustHex(s string) []byte {
	b, err := hex.DecodeString(s)
	if err != nil {
		panic(err)
	}
	return b
}

// golden: real ClientHello (python ssl client, SNI=daily-cloudcode-pa.googleapis.com)
const realHelloHex = ""

func TestParseSNI(t *testing.T) {
	t.Parallel()
	hello := mustHex(realHelloHex)
	got, ok := ParseSNI(hello)
	if !ok || got != "daily-cloudcode-pa.googleapis.com" {
		t.Fatalf("ParseSNI(real hello) = %q,%v", got, ok)
	}
	if got2, ok2 := ParseSNI(append(append([]byte{}, hello...), 0xde, 0xad)); !ok2 || got2 != "daily-cloudcode-pa.googleapis.com" {
		t.Fatalf("ParseSNI(hello+trailer) = %q,%v", got2, ok2)
	}
	deny := []struct {
		name string
		data []byte
	}{
		{"not tls", []byte("GET / HTTP/1.1\r\n\r\n")},
		{"empty", nil},
		{"record header only", mustHex("16030100")},
		{"truncated payload", mustHex("160301000501000001")},
		{"wrong content type", append([]byte{0x17}, hello[1:]...)},
	}
	for _, tt := range deny {
		t.Run(tt.name, func(t *testing.T) {
			if _, ok := ParseSNI(tt.data); ok {
				t.Fatalf("ParseSNI(%s) unexpectedly succeeded", tt.name)
			}
		})
	}
}
